    emit(Oadd, Kl, r1, ap, CON_Z if isint else c4)
    emit(Oadd, Kw, r0, nr, c8 if isint else c16)
    r0 = newtmp("abi", Kl, fn)
    r1 = newtmp("abi", Kl, fn)
    emit(Oadd, Kl, lreg, r1, nr)
    emit(Oload, Kl, r1, r0, R)
    emit(Oadd, Kl, r0, ap, c16)
