        u = t.use[k]
        if u.type == UPhi:
            p = u.u
            if p.visit or p.to == R:
                continue
            p.visit = 1
            if uwl(fn, p.to, w):
                continue
        elif u.type == UIns:
            i = u.u
            assert i is not None
            if i.op == Ocopy:
                if uwl(fn, i.to, w):
                    continue
            e = ext(i)
            if e:
                if e[2] <= w:
                    continue
                if uwl(fn, i.to, w):
                    continue
            if i.op == Oand:
                if r == i.arg[0]:
                    rc = i.arg[1]
                else:
                    assert r == i.arg[1]
                    rc = i.arg[0]
