    for n in range(2):
        for c in range(2):
            if p.arg[n] == con01[c]:
                s[c] = p.blk[n]
    if (d.s1 is s[1] and d.s2 is s[0]
            and d.s1.jmp.type == Jjmp
            and d.s2.jmp.type == Jjmp):
        return d.jmp.arg
    return R
