            if op <= Ocmps1:
                c = op - Ocmps
                lf = bitsf(lu)
                rf = bitsf(ru)
            else:
                c = op - Ocmpd
                lf = bitsd(lu)
                rf = bitsd(ru)
            if c == Cfle:
                x = lf <= rf
            elif c == Cflt:
                x = lf < rf
            elif c == Cfgt:
                x = lf > rf
            elif c == Cfge:
                x = lf >= rf
            elif c == Cfne:
                x = lf != rf
            elif c == Cfeq:
                x = lf == rf
            elif c == Cfo:
                x = lf < rf or lf >= rf
            elif c == Cfuo:
                x = not (lf < rf or lf >= rf)
            else:
                die("unreachable")
