def _fdiv(a, b):
    if b == 0.0:
        if a != a:
            return a
        if a == 0.0:
            return math.nan
        neg = (math.copysign(1.0, a) < 0) != (math.copysign(1.0, b) < 0)
        return -math.inf if neg else math.inf
    return a / b
def opfold(op, cls, cl, cr, fn):
    c = Con()
    if cls == Kw or cls == Kl:
        if foldint(c, op, cls == Kl, cl, cr):
            return R
    else:
        if cl.type != CBits or cr.type != CBits:
            return R
        foldflt(c, op, cls == Kd, cl, cr)
