    b = fn.start
    while b:
        ins = b.ins[:b.nins]
        groups = []
        k = 0
        while k < len(ins):
            i0, i1 = igroup(b, k)
            groups.append(ins[i0:i1])
            k = i1
        owner = {}
        for n, g in enumerate(groups):
            for i in g:
                if rtype(i.to) == RTmp:
                    owner[rval(i.to)] = n
        fixed = [any(pinned(i) for i in g) for g in groups]
        emitted = [False] * len(groups)
        out = []
        def place(n, busy):
            if emitted[n]:
                return True
            if n in busy:
                return False
            busy.add(n)
            for i in groups[n]:
                for a in i.arg[:2]:
                    if rtype(a) != RTmp:
                        continue
                    m = owner.get(rval(a))
                    if m is None or m == n or emitted[m]:
                        continue
                    if fixed[m] or not place(m, busy):
                        busy.discard(n)
                        return False
            busy.discard(n)
            for i in groups[n]:
                if i.op != Onop:
                    out.append(i.copy())
            emitted[n] = True
            return True
        waiting = []
        def flush():
            again = True
            while again:
                again = False
                for n in list(waiting):
                    if place(n, set()):
                        waiting.remove(n)
                        again = True
        for n in range(len(groups)):
            if fixed[n]:
                if not place(n, set()):
                    die("a pinned instruction reads what comes after it in its block")
            elif not place(n, set()):
                waiting.append(n)
            flush()
        if waiting:
            die("a cycle within a block")
