import sys
from . import defs as D
from . import copy as C
from .defs import (R, RTmp, CON_Z, CBits, Con, Ins, KBASE, KWIDE, U32, Kx, Kw, Kl, UXXX,
                   UPhi, UIns, UJmp, Jjmp, Jjnz, Onop, Osub, Oadd, Osel0, optab, rtype,
                   rval, rkind, s32)
from .util import die, getcon, newcon, isconbits, argcls, addins, iscmp
from .cfg import dom, reachesnotvia, fillcfg, fillloop
from .fold import foldint, foldref
from .gcm import pinned, isdivwl
from . import ext as _ext
con01 = [R, R]
def mix(x0, x1):
    return (x0 + 17 * x1) & U32
def rhash(r):
    return mix(rkind(r), rval(r))
def ihash(i):
    h = mix(i.op, i.cls & U32)
    h = mix(h, rhash(i.arg[0]))
    h = mix(h, rhash(i.arg[1]))
    return h
def ieq(ia, ib):
    if ia.op == ib.op:
        if ia.cls == ib.cls:
            if ia.arg[0] == ib.arg[0]:
                if ia.arg[1] == ib.arg[1]:
                    return 1
    return 0
gvntbl = None
gvntbln = 0
gvndivs = {}
gvnselects = {}
gvnjmps = {}
def gvndup(i, insert):
    idx = ihash(i) % gvntbln
    while True:
        ii = gvntbl[idx]
        if ii is None:
            break
        if ieq(i, ii):
            return ii
        idx += 1
        if gvntbln <= idx:
            idx = 0
    if insert:
        gvntbl[idx] = i
    return None
def replaceuse(fn, u, r1, r2):
    from .ssa import adduse
    t2 = None
    if rtype(r2) == RTmp:
        t2 = fn.tmp[rval(r2)]
    b = fn.rpo[u.bid]
    if u.type == UPhi:
        p = u.u
        for n in range(p.narg):
            if p.arg[n] == r1:
                p.arg[n] = r2
        if t2:
            adduse(t2, UPhi, b, p)
    elif u.type == UIns:
        i = u.u
        for n in range(2):
            if i.arg[n] == r1:
                i.arg[n] = r2
        if t2:
            adduse(t2, UIns, b, i)
    elif u.type == UJmp:
        if b.jmp.arg == r1:
            b.jmp.arg = r2
