        cfg.fillcfg(fn)
        live.filllive(fn)
        cfg.fillloop(fn)
        spill.fillcost(fn)
        spill.spill(fn)
        rega.rega(fn)
        cfg.fillcfg(fn)
        cfg.simpljmp(fn)
        cfg.fillcfg(fn)
