        _nop(t.def_)
        ts = fn.tmp[s.s.t]
        assert t.bid == ts.bid
        bb = fn.rpo[t.bid]
        if _insidx(bb, t.def_) < _insidx(bb, ts.def_):
            t.def_.set(ts.def_)
            _nop(ts.def_)
            ts.def_ = t.def_
        for u in t.use[:t.nuse]:
            if u.type == UJmp:
                b = fn.rpo[u.bid]
                b.jmp.arg = TMP(s.s.t)
                continue
            assert u.type == UIns
            arg = u.u.arg
            for n in range(2):
                if arg[n] == TMP(s.t):
                    arg[n] = TMP(s.s.t)
