        emiti(b.ins[i1])
        ii = D.curi
        i = insb[ii]
        rf = -1
        skip = False
        if i.op == Ocall:
            rs = T.argregs(i.arg[1], None) | T.rglob
            r = 0
            while T.rsave[r] >= 0:
                if not (BIT(T.rsave[r]) & rs):
                    rfree(cur, T.rsave[r])
                r += 1
