    global tmp, ntmp, locs, slot4, slot8
    from .live import liveon
    T = D.T
    tmp = fn.tmp
    ntmp = fn.ntmp
    u = BSet()
    v = BSet()
    w = BSet()
    bsinit(u, ntmp)
    bsinit(v, ntmp)
    bsinit(w, ntmp)
    bsinit(mask[0], ntmp)
    bsinit(mask[1], ntmp)
    locs = fn.slot
    slot4 = 0
    slot8 = 0
    lvarg = [0, 0]
    for t in range(ntmp):
        k = 0
        if T.fpr0 <= t < T.fpr0 + T.nfpr:
            k = 1
        if t >= Tmp0:
            k = KBASE(tmp[t].cls)
        bsset(mask[k], t)
    for bi in range(fn.nblk - 1, -1, -1):
        b = fn.rpo[bi]
        D.curi = 0
        s1 = b.s1
        s2 = b.s2
        hd = None
        if s1 and s1.id <= b.id:
            hd = s1
        if s2 and s2.id <= b.id:
            if not hd or s2.id >= hd.id:
                hd = s2
        if hd:
            bszero(v)
            hd.gen.t |= T.rglob
            for k in range(2):
                n = T.ngpr if k == 0 else T.nfpr
                bscopy(u, b.out)
                bsinter(u, mask[k])
                bscopy(w, u)
                bsinter(u, hd.gen)
                bsdiff(w, hd.gen)
                if bscount(u) < n:
                    j = bscount(w)
                    l = hd.nlive[k]
                    limit(w, s32(n - (l - j)), None)
                    bsunion(u, w)
                else:
                    limit(u, n, None)
                bsunion(v, u)
        elif s1:
            bszero(v)
            liveon(w, b, s1)
            merge(v, b, w, s1)
            if s2:
                liveon(u, b, s2)
                merge(v, b, u, s2)
                bsinter(w, u)
            limit2(v, 0, 0, w)
        else:
            bscopy(v, b.out)
            if rtype(b.jmp.arg) == RCall:
                v.t |= T.retregs(b.jmp.arg, None)
        if rtype(b.jmp.arg) == RTmp:
            t = rval(b.jmp.arg)
            assert KBASE(tmp[t].cls) == 0
            bsset(v, t)
            limit2(v, 0, 0, None)
            if not bshas(v, t):
                b.jmp.arg = slot(t)
        for t in bselems(b.out, Tmp0):
            if not bshas(v, t):
                slot(t)
        bscopy(b.out, v)
        D.curi = NIns
        i = b.nins
        while i != 0:
            i -= 1
            ins = b.ins[i]
            if regcpy(ins):
                i = dopm(b, i, v)
                continue
            bszero(w)
            if ins.to != R:
                assert rtype(ins.to) == RTmp
                t = rval(ins.to)
                if t < Tmp0 and BIT(t) & T.rglob:
                    pass
                elif bshas(v, t):
                    bsclr(v, t)
                else:
                    assert t >= Tmp0, "dead reg"
                    bsset(v, t)
                    bsset(w, t)
            j = T.memargs(ins.op)
            for n in range(2):
                if rtype(ins.arg[n]) == RMem:
                    j -= 1
            for n in range(2):
                rt = rtype(ins.arg[n])
                if rt == RMem:
                    t = rval(ins.arg[n])
                    m = fn.mem[t]
                    if rtype(m.base) == RTmp:
                        bsset(v, rval(m.base))
                        bsset(w, rval(m.base))
                    if rtype(m.index) == RTmp:
                        bsset(v, rval(m.index))
                        bsset(w, rval(m.index))
                elif rt == RTmp:
                    t = rval(ins.arg[n])
                    lvarg[n] = bshas(v, t)
                    bsset(v, t)
                    jj = j
                    j -= 1
                    if jj <= 0:
                        bsset(w, t)
            keep = (ins.op in D.QACC or ins.op == D.Oqsel1) and ins.to != R and rval(ins.to) >= Tmp0
            if keep:
                bsset(v, rval(ins.to))
                bsset(w, rval(ins.to))
            bscopy(u, v)
            limit2(v, 0, 0, w)
            for n in range(2):
                if rtype(ins.arg[n]) == RTmp:
                    t = rval(ins.arg[n])
                    if not bshas(v, t):
                        if not lvarg[n]:
                            bsclr(u, t)
                        ins.arg[n] = slot(t)
            reloads(u, v)
            if ins.to != R:
                t = rval(ins.to)
                store(ins.to, tmp[t].slot)
                if t >= Tmp0:
                    bsclr(v, t)
                if keep:
                    bsset(v, t)
            emiti(ins)
            r = v.t & M64
            if r:
                sethint(v, r)
        if b is fn.start:
            assert (v.t & M64) == (T.rglob | fn.reg)
        else:
            assert (v.t & M64) == T.rglob
        p = b.phi
        while p:
            assert rtype(p.to) == RTmp
            t = rval(p.to)
            if bshas(v, t):
                bsclr(v, t)
                store(p.to, tmp[t].slot)
            elif bshas(b.in_, t):
                p.to = slot(rval(p.to))
            p = p.link
        bscopy(b.in_, v)
        idup(b, D.curi, NIns - D.curi)
    slot8 += slot8 & 3
    fn.slot += slot8
    if D.debug['S']:
        err = sys.stderr
        err.write("\\n> Block information:\\n")
        b = fn.start
        while b:
            err.write("\\t%-10s (% 5d) " % (b.name, b.loop))
            dumpts(b.out, fn.tmp, err)
            b = b.link
        err.write("\\n> After spilling:\\n")
        printfn(fn, err)
