def _cache_dirs():
    from .. import driver, linker
    mods = driver._cache_dir()
    root = linker._cache_root() if hasattr(linker, '_cache_root') else mods
    return mods, root
def _cache_entries():
    mods_dir, rt_root = _cache_dirs()
