def stack_checked(ssa):
    import re
    funcs = {}
    taken = set()
    cur = None
    for line in ssa.splitlines():
        m = re.match(r'(?:export\\s+)?(?:vector \\d+ )?function\\s+(?:\\S+\\s+)?\\$([\\w.]+)\\(', line)
        if m:
            cur = m.group(1)
            funcs[cur] = [set(), False]
            continue
        if line.startswith('}'):
            cur = None
            continue
        calls = re.findall(r'\\bcall\\s+(?:extern\\s+)?([$%][\\w.]+)', line)
        refs = re.findall(r'\\$([\\w.]+)', line)
        if cur is not None:
            for c in calls:
                if c[0] == '$':
                    funcs[cur][0].add(c[1:])
                else:
                    funcs[cur][1] = True
            called = set(c[1:] for c in calls if c[0] == '$')
            taken.update(r for r in refs if r not in called or line.count('$' + r) > 1)
        else:
            taken.update(refs)
    graph = {f: set(c for c in cs if c in funcs) | (set(t for t in taken if t in funcs)
                                                    if ind else set())
             for f, (cs, ind) in funcs.items()}
    index, low, on, stack, out = {}, {}, set(), [], set()
    counter = [0]
    for root in graph:
        if root in index:
            continue
        work = [(root, iter(graph[root]))]
        index[root] = low[root] = counter[0]
        counter[0] += 1
        stack.append(root)
        on.add(root)
        while work:
            v, it = work[-1]
            for w in it:
                if w not in index:
                    index[w] = low[w] = counter[0]
                    counter[0] += 1
                    stack.append(w)
                    on.add(w)
                    work.append((w, iter(graph[w])))
                    break
                if w in on:
                    low[v] = min(low[v], index[w])
            else:
                work.pop()
                if work:
                    low[work[-1][0]] = min(low[work[-1][0]], low[v])
                if low[v] == index[v]:
                    scc = []
                    while True:
                        w = stack.pop()
                        on.discard(w)
                        scc.append(w)
                        if w == v:
                            break
                    if len(scc) > 1 or v in graph[v]:
                        out.update(scc)
    return frozenset(out)
