def declspecs(s, sc, fs, align):
    ts = SPECNONE
    tq = Ref(QUALNONE)
    ntypes = 0
    typeofexpr = None
    bits = 0
    t = None
    if sc:
        sc.v = SCNONE
    if fs:
        fs.v = FUNCNONE
    if align:
        align.v = 0
    while True:
        if typequal(tq) or storageclass(sc) or funcspec(fs):
            continue
        op = tok.kind
        if op == TVOID:
            t = TY.typevoid
            ntypes += 1
            next()
        elif op == TCHAR:
            ts |= SPECCHAR
            ntypes += 1
            next()
        elif op == TSHORT:
            if ts & SPECSHORT:
                error(tok.loc, "duplicate 'short'")
            ts |= SPECSHORT
            next()
        elif op == TINT:
            ts |= SPECINT
            ntypes += 1
            next()
        elif op == TLONG:
            if ts & SPECLONG2:
                error(tok.loc, "too many 'long'")
            if ts & SPECLONG:
                ts |= SPECLONG2
            ts |= SPECLONG
            next()
        elif op == TFLOAT:
            ts |= SPECFLOAT
            ntypes += 1
            next()
        elif op == TDOUBLE:
            ts |= SPECDOUBLE
            ntypes += 1
            next()
        elif op == TSIGNED:
            if ts & SPECSIGNED:
                error(tok.loc, "duplicate 'signed'")
            ts |= SPECSIGNED
            next()
        elif op == TUNSIGNED:
            if ts & SPECUNSIGNED:
                error(tok.loc, "duplicate 'unsigned'")
            ts |= SPECUNSIGNED
            next()
        elif op == T_BITINT:
            ts |= SPECBITINT
            ntypes += 1
            next()
            expect(TLPAREN, "after _BitInt")
            bits = E.intconstexpr(s, False)
            expect(TRPAREN, "after _BitInt width")
        elif op == TBOOL:
            t = TY.typebool
            ntypes += 1
            next()
        elif op == T_COMPLEX:
            if not U.diagnostics:
                error(tok.loc, "_Complex is not yet supported")
            if ts & SPECCOMPLEX:
                error(tok.loc, "duplicate '_Complex'")
            ts |= SPECCOMPLEX
            next()
        elif op == T_ATOMIC:
            error(tok.loc, "_Atomic is not yet supported")
