def _link(t):
    if t.link is None:
        t.link = ListNode(t)
    return t.link
def declaratortypes(s, result, name, align, funcscope, allowabstract):
    while consume(TMUL):
        A.attr(None, 0)
        tq = Ref(QUALNONE)
