            e.qual = tq.v
            e.lvalue = True
            d = D.mkdecl(None, DECLOBJECT, t, tq.v, LINKNONE)
            d.storage = SDSTATIC if s is SC.filescope else SDAUTO
            e.decl = d
            e.init = Init(m.offset, m.offset + m.type.size, BITS0, exprassign(x, m.type))
            e = postfixexpr(s, decay(e))
