    red = U.reduce and l.kind == EXPRIDENT and U.reduce.get(id(l.decl))
    if red and l.type.prop & PROPFLOAT and not l.type.iscomplex:
        red = _REDUCE[red]
    else:
        red = ()
    if not op:
        if r.kind == EXPRBINARY and r.op in red and r.type is l.type:
            r.reassoc = True
        return mkassignexpr(l, r)
    if l.kind == EXPRBITFIELD:
        bit = l
        l = l.base
    else:
        bit = None
    tmp = Expr(EXPRTEMP, mkpointertype(l.type, l.qual), None)
    tmp.lvalue = True
    tmp.temp = None
    e = mkassignexpr(tmp, mkunaryexpr(TBAND, l))
