    while t.kind != TNEWLINE and t.kind != TEOF:
        if t.kind == THASHHASH:
            error(t.loc, "'##' operator is not yet implemented")
        prev = t.kind
        t = Token()
        repl.append(t)
        S.scan(t)
        if t.kind == T__VA_ARGS__ and not macrovarargs(m):
            error(t.loc, "__VA_ARGS__ can only be used in variadic function-like macros")
