    if sz == 1:
        return _sb if t.issigned else _ub
    if sz == 2:
        return _uh if t.prop & PROPFLOAT else _sh if t.issigned else _uh
    if sz == 4:
        return _s if t.prop & PROPFLOAT else _w
    if sz == 8:
        return _d if t.prop & PROPFLOAT else _l
