import contextlib
enabled = False
params = {}
vectorizing = __import__('os').environ.get('CIMO_VECTORIZE', '1') != '0'
unroll = 4
debug = False
stats = None
gpu = False
_NAMES = ('enabled', 'params', 'unroll', 'debug', 'stats', 'vectorizing', 'gpu')
def configure(**kw):
    g = globals()
    old = {k: g[k] for k in _NAMES}
    for k, v in kw.items():
        if k not in _NAMES:
            raise TypeError('unknown middle-end option %r' % k)
        g[k] = v
    return old
@contextlib.contextmanager
def options(**kw):
    old = configure(**kw)
    try:
        yield
    finally:
        configure(**old)
def count(name, n=1):
    if stats is not None:
        stats[name] = stats.get(name, 0) + n
def run(fn):
    from .pipeline import optimize
    return optimize(fn)
