    em = Emitter(fn, RB)
    outR, _ = fast.copies(em, stR, 1)
    outR = fast.advance(em, outR, 1)
    c = em.raw(D.Ocnel if kc == Kl else D.Ocnew, Kw, outR[('iv', ctlg.idx)], end)
    em.flush()
