        while e < to:
            op = 'qsx' if signed else 'qux'
            out = []
            for v in vs:
                out.append(em.raw(getattr(D, 'O' + op + 'l' + _UX[e]), Kq, v))
                out.append(em.raw(getattr(D, 'O' + op + 'h' + _UX[e]), Kq, v))
